import functools
import time

def retry_decorator(max_attempts, delay, exceptions):
    """
    Decorador para reintentar la función decorada hasta que no se produzca 
    ninguna excepción permitida o se agoten los max_attempts.

    Parametros:
        max_attempts (int): Número máximo de intentos antes de lanzar la última excepción.
        delay (float): Tiempo en segundos a esperar entre intentos.
        exceptions (tuple): Tupla de tipos de excepciones permitidas para reintentar.

    Retorna:
        Función decorada.
    """
    def decorator(func):
        @functools.wraps(func)
        def wrapper(*args, **kwargs):
            last_exception = None
            try:
                return func(*args, **kwargs)
            except Exception as e:
                if e in exceptions:
                    last_exception = e
                    time.sleep(delay)
                    continue
                raise

        return wrapper
    return decorator
