from retry_decorator import retry

@retry(max_attempts=3, delay=1.0, exceptions=(IOError, TimeoutError))
def fetch_data(url):
    """
    Función que intenta obtener datos desde una URL.
    """
    try:
        response = urllib.request.urlopen(url)
        return response.read().decode()
    except IOError:
        print("Error de red")
        raise
    except TimeoutError:
        print("Tiempo de espera excedido")
        raise
    except Exception as e:
        print(f"Otra excepción: {e}")
        raise

if __name__ == "__main__":
    try:
        data = fetch_data("https://httpbin.org/ip")
        print(data)
    except Exception as e:
        print(f"Final error: {e}")
